  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Claude 通过 OAuth 登录，因此无需粘贴密钥：你按下 Allow 后它会获得自己的密钥。不登录的话，可将其作为<b>其他应用</b>连接，并发送请求头 <code>Authorization: Bearer &lt;key&gt;</code>。",
