  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "删除的对话及其消息将永久消失。你的笔记不受影响，正在回答的对话也会保留。",
  "Deleted notes": "已删除的笔记",
  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "已删除的笔记会保留在这里，直到你恢复或永久删除它们。恢复时，你可以选择笔记的去处：原文件夹、其他文件夹或顶层。",
