  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "将卡片拖入另一个文件夹框，即可在磁盘上移动该笔记。拖动框的名称可重新排列画板；将其放到另一个框上可把整个文件夹移过去。双击标题重命名。触屏：拖动平移，双指缩放，长按卡片移动，轻点预览。",
  "Drag a note here to pin it": "将笔记拖到此处即可置顶",
