  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "将笔记或文件夹拖到某个文件夹上即可移动，拖到“置顶”即可置顶。",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "拖动笔记 · 双击固定 · / 搜索 · #标签 查找标签 · F 适应 · 1 2 3 布局",
  "Drag to move the folder frame; double-click to rename": "拖动以移动文件夹框；双击重命名",
  "Drag to resize · double-click to reset": "拖动调整大小 · 双击恢复",
  "Drag to turn · scroll to zoom · click a point to open its note": "拖动旋转 · 滚动缩放 · 点击光点打开笔记",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "拖动旋转 · 滚动缩放 · 点击光点打开笔记 · / 搜索 · #标签 查找标签",
