  "Dyslexic": "读写障碍",
  "Each AI app connects over MCP with its own key and permissions.": "每个 AI 应用都通过 MCP 连接，使用各自的密钥和权限。",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "每个连接的 AI 应用都是一个拥有独立密钥的智能体，你可以看到每个智能体做了什么，并单独关闭它。",
  "Each agent": "每个智能体",
  "Each agent belongs to one app. For another app or device, make a new agent.": "每个智能体只属于一个应用。其他应用或设备请新建智能体。",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "每个智能体只属于一个应用。要在其他应用中使用 Memora，请为它单独创建智能体。",
  "Each app gets its own key": "每个应用都有自己的密钥",
  "Each has a short id that never changes, so names can change freely. Mnemo sets them up, changes their instructions or model, messages, waits for, stops, finishes and removes them, one or all at once, and can let them work in the background. Each card shows Instruction, Activity and Answer.": "每个子代理都有一个永不改变的短 ID，名字可以随意改。Mnemo 可以创建、修改指令或模型、发消息、等待、停止、完成和移除它们，可单个也可全部一次处理，还能让它们在后台工作。每张卡片都显示指令、活动和回答。",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "每类按各自的空间计算：设置了上限时按上限，否则按已用量加磁盘剩余空间{disk}。上限留空表示不限。",
  "Each one gets its own key from Memora.": "每个应用都会从 Memora 获得自己的密钥。",
