  "Enter your password": "请输入密码",
  "Entries": "条目",
  "Error": "错误",
  "Error 404": "错误 404",
  "Even in daily use, a browser signs in again after this long. It cannot be shorter than the inactivity time.": "即使每天使用，浏览器在此时长后也需重新登录。不能短于闲置时长。",
  "Every AI loses {n} tool at once. Asks first.": "所有 AI 将立即失去 {n} 个工具。会先询问。",
  "Every AI loses {n} tools at once. Asks first.": "所有 AI 将立即失去 {n} 个工具。会先询问。",
  "Every action, newest first": "所有操作，最新在前",
  "Every action, newest first, with search and filters.": "所有操作，最新在前，支持搜索和筛选。",
  "Every address from one to another.": "从一个地址到另一个地址的全部地址。",
  "Every address from the first to the last, joined by a dash.": "从起始到结束的所有地址，用短横线连接。",
  "Every agent usually starts from zero. {bold} connect each agent once and they all read the same vault and write back to it, so what one learns, the others can use.": "每个智能体通常都从零开始。{bold}每个智能体只需连接一次，它们都读取同一个库并写回其中，一个学到的，其他的都能用。",
  "Every browser and agent is disconnected until someone starts Memora again on that machine. This page cannot start it again.": "在有人于该机器上重新启动 Memora 之前，所有浏览器和智能体都会断开。此页面无法重新启动它。",
  "Every call shows up live in the brain and Activity": "每次调用都会实时显示在大脑和活动中",
  "Every change Mnemo makes shows in Activity and can be undone from History.": "Mnemo 做的每处更改都会显示在活动中，并可在历史中撤销。",
  "Every change, by you or an app, shows in Activity and can be undone from History.": "每处更改，无论来自你还是应用，都会显示在活动中，并可在历史中撤销。",
  "Every chat is archived.": "所有对话都已归档。",
  "Every chat with your notes agent": "与笔记智能体的所有对话",
  "Every connected AI loses all {n} tools at once and can no longer read or change your notes until you turn tools back on here.": "所有已连接的 AI 将立即失去全部 {n} 个工具，在你于此重新开启之前无法读取或更改你的笔记。",
  "Every connected AI loses it at once. You can turn it back on any time.": "所有已连接的 AI 将立即失去它。你可以随时重新开启。",
  "Every connected AI loses them at once. You can turn them back on any time.": "所有已连接的 AI 将立即失去它们。你可以随时重新开启。",
  "Every connected agent loses its memory until Memora runs again.": "在 Memora 重新运行前，所有已连接的智能体都会失去记忆。",
  "Every device on a home or office network, written as address/size: 192.168.1.0/24 covers 192.168.1.0 to 192.168.1.255.": "家庭或办公网络中的所有设备，写作 地址/大小：192.168.1.0/24 覆盖 192.168.1.0 到 192.168.1.255。",
  "Every device on a home or office network.": "家庭或办公网络中的所有设备。",
  "Every image in the notes folder and where it is shown, and the pictures kept for Mnemo chats.": "笔记文件夹中的所有图片及其显示位置，以及为 Mnemo 对话保存的图片。",
  "Every image is used in a note.": "所有图片都在笔记中使用。",
  "Every note": "所有笔记",
  "Every note and link, in 3D, as a graph or on a board.": "所有笔记和链接，以 3D、图谱或白板呈现。",
  "Every note and subfolder in \"{path}\" moves into {folder}; \"{name}\" is then removed. If a name is already taken there, a number is added to it.": "“{path}”中的所有笔记和子文件夹将移到 {folder}；随后移除“{name}”。如果名称已被占用，会在名称后添加数字。",
  "Every note becomes a card here, inside a frame for its folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "每条笔记都会在这里成为一张卡片，放在其文件夹的框内。指南会说明如何让 AI 把知识保存到这里，或自己写一条笔记。",
  "Every note becomes a point of light here, grouped by folder. The guide shows how to have an AI save its knowledge here, or write a note yourself.": "每条笔记都会在这里成为一个光点，按文件夹分组。指南会说明如何让 AI 把知识保存到这里，或自己写一条笔记。",
  "Every note tagged #{tag} ({notes}) gets the new name, inline #tags in the text too.": "所有带有 #{tag} 的笔记（{notes}）都会使用新名称，正文中的 #标签 也会更改。",
  "Every note tagged {tags} gets one tag instead ({notes}). Inline #tags in the text change too. There is no one-step undo; each note keeps its history.": "所有带有 {tags} 的笔记都会改为同一个标签（{notes}）。正文中的 #标签 也会更改。无法一键撤销；每条笔记都保留历史。",
  "Every read and write by an agent shows up live, so you always know who did what.": "智能体的每次读写都会实时显示，你总能知道谁做了什么。",
  "Every request that reaches this rule is {verb}.": "到达此规则的每个请求都会{verb}。",
  "Every request. Put it last, to catch whatever the rules above did not.": "所有请求。放在最后，用来兜住上面规则未匹配的请求。",
  "Every setting and where it lives.": "所有设置及其所在位置。",
  "Every shortcut in the web UI.": "Web 界面中的所有快捷键。",
  "Every tag and its notes": "所有标签及其笔记",
  "Every tool agents can call": "智能体可调用的所有工具",
  "Every tool that is on for the server, including new ones.": "服务器上已开启的所有工具，包括新增的工具。",
  "Everyone": "所有人",
