  "Get started": "快速开始",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "通过我的笔记来了解我。浏览我的保险库（最近的笔记、日记、项目，任何与我有关的内容），并用 remember_owner 记下你了解到的：我是谁、我在做什么、我喜欢怎样的回答、我喜欢什么。只记简短而持久的内容，绝不记密码等机密。然后用几行告诉我你记了什么。",
  "Gets its own agent key: read and write nodes over MCP": "获得专属代理密钥：通过 MCP 读写节点",
  "Getting started": "入门",
  "GitHub answered HTTP {code}": "GitHub 返回 HTTP {code}",
  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "为 Claude、Cursor 或任意 MCP 应用分配专属密钥，然后让它保存它已了解的关于你的信息。",
  "Give a key read-only access, or let it write too.": "给密钥只读权限，或者也允许它写入。",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "为每个应用或设备分配单独的智能体。这样活动记录能准确显示谁做了什么，你也可以关闭其中一个而不影响其他。",
  "Give it a name you recognise": "起一个你认得出的名字",
