  "How {mnemo} works": "{mnemo} 的工作方式",
  "Humanist": "人文",
  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "我可以查找、阅读、撰写、标记、链接和整理你的笔记。不联网，不用命令行：只在你的库中。",
  "Icon": "图标",
