  "Identity": "身份",
  "Idle": "空闲",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "如果它对你有帮助，在 GitHub 点个 Star 或告诉朋友，能让更多人发现它。不点也完全没关系。",
  "If you leave, they are kept on this device and offered again when you open the note.": "如果离开，它们会保留在此设备上，并在你再次打开笔记时提供恢复。",
  "Image": "图片",
