  "Images in this folder": "此文件夹中的图片",
  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "图片保存在展示它们的笔记旁边。选择单张图片的大小上限，并查看笔记和图片的占用。",
  "Import and export": "导入与导出",
  "Imported": "已导入",
  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "在 ChatGPT 中打开 <b>Settings → Apps &amp; Connectors → Advanced settings</b>，开启 <b>Developer mode</b>。然后选择 <b>Create</b>。",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "在 Claude（网页或桌面版）中打开 <b>Settings → Connectors</b>，选择 <b>Add custom connector</b>。",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "在 Claude Desktop 中打开 <b>Settings → Developer → Edit Config</b>。较新版本请改选 <b>Claude</b>。",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "在 Windsurf 中打开 <b>Settings → Cascade → MCP servers</b>，选择 <b>View raw config</b>。",
  "In note text": "笔记正文中",
  "In notes": "所在笔记",
