  "Installed": "已安装",
  "Installing, connecting agents, settings and reference.": "安装、连接智能体、设置和参考。",
  "Instance not ready": "实例未就绪",
  "Instruction": "指令",
  "Instruction style": "指令风格",
  "Instructions": "指令",
  "Instructions from {mnemo}": "来自 {mnemo} 的指令",
  "Interface": "界面",
  "Internet (tunnel)": "互联网（隧道）",
  "Internet address (IP)": "互联网地址（IP）",
  "It becomes your first rule.": "这将是你的第一条规则。",
  "It becomes {path}. Links to its notes keep working.": "它将变为 {path}。指向其笔记的链接仍然有效。",
  "It can change notes, but nothing lets it connect.": "它可以更改笔记，但没有任何方式让它连接。",
  "It can search and read your notes, but not change them": "它可以搜索和读取你的笔记，但不能更改",
  "It can search, read and save your notes": "它可以搜索、读取和保存你的笔记",
  "It can {list}.": "它可以{list}。",
  "It cannot do anything yet": "它暂时什么都不能做",
  "It has full control: it reads and changes notes, and can manage Memora and other agents": "它拥有完全控制权：可读取和更改笔记，并能管理 Memora 和其他智能体",
  "It holds {n} note. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "其中有 {n} 条笔记。接下来你将选择如何处理它们：移到其他文件夹，或移到回收站。目前尚未做任何更改。",
  "It holds {n} notes. Next you choose what happens to them: move them to another folder, or move them to the Trash. Nothing is changed yet.": "其中有 {n} 条笔记。接下来你将选择如何处理它们：移到其他文件夹，或移到回收站。目前尚未做任何更改。",
  "It is added at the end, as rule {n}, so it is checked last.": "它会作为规则 {n} 添加到末尾，最后检查。",
  "It is gone when you leave, pictures included. Changes to your notes still show in Activity and History.": "离开后它就会消失，图片也一样。对笔记的更改仍会显示在活动和历史中。",
  "It is kept locked on the server. Enter your Memora password and the buttons below put it in for you.": "它在服务器上被锁定保存。输入你的 Memora 密码，下方按钮会替你填入。",
  "It is taking a while. Check the server, then reload this page.": "耗时较长。请检查服务器，然后重新加载此页面。",
  "It leaves the Pinned list only; the folder itself stays where it is.": "仅从置顶列表移除；文件夹本身保持原位。",
  "It leaves the Pinned list only; the note itself stays where it is.": "仅从置顶列表移除；笔记本身保持原位。",
  "It may have been renamed, moved or deleted. Deleted notes wait in the Trash.": "它可能已被重命名、移动或删除。已删除的笔记在回收站中。",
  "It moves; links to it are updated and pins follow.": "它将被移动；指向它的链接会更新，置顶也会跟随。",
  "It must sign in again and is told why": "需要重新登录，并会收到原因说明",
  "It prints a one-time code. This page moves on by itself.": "它会打印一个一次性代码。此页面会自动继续。",
  "It reached Memora but did not finish. It often works on the next try.": "请求已到达 Memora 但未完成。通常重试即可成功。",
  "It reached Memora but did not finish: {error} It often works on the next try.": "请求已到达 Memora 但未完成：{error} 通常重试即可成功。",
  "It shows up under this name in Activity, the brain and the graph. Name it after the device when you use {app} in more than one place, like \"{example}\".": "它会以此名称显示在活动、大脑和图谱中。如果你在多个地方使用 {app}，请按设备命名，例如“{example}”。",
  "It was shown when it was made. Make a new key to see one again.": "它在生成时显示过。生成新密钥才能再次看到。",
  "Italic": "斜体",
  "Its API key and its models are removed. Chats stay; a chat that used one of its models switches to the default.": "其 API 密钥和模型将被删除。对话会保留；使用其模型的对话会切换到默认模型。",
  "Its key and access stay the same in every notes folder. Connect another one any time.": "它的密钥和权限在每个笔记文件夹中都保持不变。随时可以再连接一个。",
  "Its key is filled in on the next step": "密钥会在下一步填入",
  "Its key is refused until you turn it back on. Nothing is deleted.": "在重新开启前它的密钥会被拒绝。不会删除任何内容。",
  "Its key is refused. Turn it on to let it connect again with the same key.": "它的密钥会被拒绝。开启后可用同一密钥重新连接。",
  "Its key stopped working. You can restore it until you reload the app.": "它的密钥已失效。在重新加载应用之前都可以恢复。",
  "Its key stops working at once. Past activity stays; you can restore it until you reload the app.": "它的密钥会立即失效。过去的活动保留；在重新加载应用前都可以恢复。",
  "Its key was shown only once, when it was made. A new key replaces it and the old one stops working at once.": "它的密钥只在创建时显示过一次。新密钥会替换它，旧密钥立即失效。",
  "Its notes are in its folders. You can also start one here.": "它的笔记在其子文件夹中。你也可以在这里新建一条。",
  "Its numbers, timeline and export.": "它的数据、时间线和导出。",
  "Its old folder is not known, so it goes to the top level": "原文件夹未知，因此将放到顶层",
  "Its page": "它的页面",
  "Its page shows how to connect it.": "它的页面会说明如何连接。",
  "Its page: status, recent calls, access and settings.": "它的页面：状态、最近调用、权限和设置。",
  "Its permissions are a custom mix. Pick a level to replace them, or fine-tune them under Advanced.": "它的权限是自定义组合。选择一个级别来替换，或在“高级”中微调。",
