  "Long enough. A few more characters make it stronger.": "长度已够。再加几个字符会更安全。",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "较长的任务会在输入框上方显示为清单：未开始、进行中、已完成。",
