  "Look through the project in this folder and save it into Memora: what it is for, how it is built, how to run it, technical decisions, and anything worth remembering. Make one note per topic, in a folder named after the project inside Projects.": "浏览此文件夹中的项目并保存到 Memora：它的用途、构建方式、运行方法、技术决策以及其他值得记住的内容。每个主题写一条笔记，放在 Projects 内以项目命名的文件夹中。",
