  "Meet Mnemo, your notes agent": "认识 Mnemo，你的笔记智能体",
  "Memora address (MCP endpoint)": "Memora 地址（MCP 端点）",
  "Memora already uses this folder.": "Memora 已在使用此文件夹。",
  "Memora by Codrihub Tech": "Memora，由 Codrihub Tech 出品",
  "Memora can save notes here": "Memora 可以在此保存笔记",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Memora 会检查文件夹并在切换前请你确认。不会移动或复制任何内容，你也可以在这里切换回来。在 Docker 中运行？请使用挂载到容器中的文件夹。",
  "Memora could not start.": "Memora 无法启动。",
  "Memora data folder": "Memora 数据文件夹",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Memora 会先检查新文件夹是否存在（或能否创建）以及能否在其中保存笔记。检查失败则不做任何更改。",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Memora 会先检查新文件夹是否存在以及能否在其中保存笔记。检查失败则不做任何更改。",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Memora 说你的语言，Mnemo 边工作边展示计划，它能用什么、看什么由你决定。",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Memora 是一款你的 AI 应用也能使用的笔记应用。你在这里写作，它们读写同一套笔记，而你始终能看到哪些内容发生了变化。",
  "Memora is free and open source": "Memora 免费且开源",
  "Memora is free and open source. A star helps others find it.": "Memora 免费且开源。点个星标能帮助更多人发现它。",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Memora 是进阶的记忆：记住你和 AI 学到的一切，用得越多，记得越多。",
  "Memora is restarting": "Memora 正在重启",
  "Memora is shut down": "Memora 已关闭",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Memora 还是空的。连接一个 AI 应用，发给它一条提示词，它就会把关于你的信息保存到这里，成为你可以阅读、编辑并在大脑中查看的笔记。",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Memora 会保存你的标签列表，在你输入时给出建议。如果有标签缺失或过时，请刷新。",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "当库文件夹是 git 仓库时，Memora 会保留笔记的每个版本。在库文件夹中运行一次 {cmd}（参见文档中“配置”下的“Version history”）；此后每次更改都会保存在这里。",
  "Memora keeps it in one place:": "Memora 把它集中在一处：",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Memora 把每条笔记保存为它所运行机器上的普通 Markdown 文件。没有任何锁定：你可以用任何编辑器打开这些文件、备份它们，或放进 Git。",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Memora 通过可流式 HTTP 提供 MCP。应用在请求头 <code>Authorization: Bearer &lt;key&gt;</code> 中发送密钥。",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Memora 将在运行它的机器上停止。你的笔记会安全保存在磁盘上。",
  "Memora version": "Memora 版本",
  "Memora v{latest} is available. This server runs v{current}.": "Memora v{latest} 已发布。此服务器运行的是 v{current}。",
  "Memora, open Overview": "Memora，打开概览",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora：自己托管的笔记库，还有帮你整理的智能体。",
  "Memory used: {used} of {win}": "已用记忆：{used} / {win}",
  "Mentioned in": "被提及于",
