  "Message to {mnemo}": "发给 {mnemo} 的消息",
  "Messaged {agent}": "给 {agent} 发了消息",
  "Messages and the message box line up exactly in every width, the model picker has its own surface, the fleeting chat fits phones, and a question's options never slide away as you tap them.": "在任何宽度下消息与输入框都完全对齐，模型选择有独立的面板，临时对话适配手机，点按问题选项时选项不再移位。",
  "Middle-drag": "中键拖动",
  "Midnight": "午夜",
  "Minimap": "小地图",
  "Minimap: click or drag to move the view": "小地图：点击或拖动以移动视图",
  "Mist": "薄雾",
  "Mnemo (AI agent)": "Mnemo（AI 智能体）",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Mnemo 按钮已隐藏。可在“更多”中选择“显示 Mnemo 按钮”恢复。",
  "Mnemo goes on without sub-agents": "Mnemo 不使用子智能体继续",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Mnemo 还没有模型：请在设置 › Mnemo 中添加服务商及其模型",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Mnemo 内置于 Memora。接入你自己的 AI 密钥，然后用日常语言提问：它会帮你查找、撰写、加标签、链接和整理笔记。",
  "Mnemo is still answering in this chat": "Mnemo 仍在此对话中回答",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Mnemo 是 Memora 内置的智能体。接入你自己的 AI 密钥，用平常的话提出要求：在其他应用使用你的笔记时，它会让笔记保持井然有序。",
  "Mnemo keeps at most {n} providers; delete one first": "Mnemo 最多保存 {n} 个服务商；请先删除一个",
  "Mnemo manages its sub-agents, keeps its plan with the chat, and the chat fits every screen better.": "Mnemo 管理自己的子代理，把计划留在对话里，对话在每种屏幕上都更合适。",
  "Mnemo runs its sub-agents": "Mnemo 指挥子代理",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Mnemo 在 {n} 步后停止；说“继续”即可接着进行。",
  "Mnemo's plan, live": "Mnemo 的计划，实时更新",
  "Mnemo's question sits on its own band, its answers below as rows to tap, as many as the question needs.": "Mnemo 的问题在单独的横条上，下面是可点按的答案行，数量按问题需要而定。",
  "Mnemo, trash and settings": "Mnemo、回收站和设置",
  "Mnemo, your notes agent": "Mnemo，你的笔记智能体",
  "Model": "模型",
  "Model for {agent}": "{agent} 的模型",
  "Model id": "模型 ID",
  "Model id, e.g. gpt-5.5 or claude-opus-5-5": "模型 ID，例如 gpt-5.5 或 claude-opus-5-5",
  "Models": "模型",
  "Models for each job": "各项任务的模型",
  "Models, API keys and what the notes agent may do": "模型、API 密钥以及笔记智能体的权限",
  "Models, keys and instructions": "模型、密钥和指令",
  "Mono": "等宽",
  "More": "更多",
  "More actions": "更多操作",
  "More actions for {name}": "{name} 的更多操作",
  "More instruction styles": "更多指令风格",
  "More: export, all activity": "更多：导出、全部活动",
  "More: reload, export": "更多：重新加载、导出",
  "More: rename, move, colour, delete": "更多：重命名、移动、颜色、删除",
  "More: rename, move, pin, delete": "更多：重命名、移动、置顶、删除",
  "Most AI apps start each chat from nothing, and each keeps its own memory. With Memora, Claude, Cursor and any other app that speaks MCP read and write the same notes, so what one app learns, the others can use.": "大多数 AI 应用每次对话都从零开始，而且各自保存自己的记忆。有了 Memora，Claude、Cursor 以及其他支持 MCP 的应用会读写同一套笔记，一个应用学到的内容，其他应用也能使用。",
