  "Nothing hidden yet: tick the agents to hide it from. Right now all {n} agents can see it.": "尚未隐藏：勾选要对其隐藏的智能体。目前全部 {n} 个智能体都能看到。",
  "Nothing hidden yet: tick the agents to hide it from. Right now the only agent can see it.": "尚未隐藏：勾选要对其隐藏的智能体。目前唯一的智能体可以看到。",
  "Nothing in 24h": "24 小时内没有",
  "Nothing in note names, folders or text, and nothing spelled close to it. Try fewer letters, another spelling, or a word from inside a note.": "笔记名称、文件夹和正文中都没有，也没有拼写相近的内容。试试少输几个字、换种拼写，或用笔记里的某个词。",
  "Nothing in the last 24 hours. What your AIs do shows up here as it happens.": "过去 24 小时没有活动。你的 AI 的操作会实时显示在这里。",
  "Nothing in the log goes by “{name}”. Showing all activity.": "日志中没有名为“{name}”的记录。显示全部活动。",
  "Nothing in this range": "此范围内没有内容",
  "Nothing in your chats says “{query}”.": "你的对话中没有提到“{query}”。",
  "Nothing is allowed. Turn something on, or pause the agent instead.": "没有任何允许项。请开启某项，或改为暂停该智能体。",
  "Nothing is lost: the current text stays in the history as v{n}, so you can switch back at any time.": "不会丢失任何内容：当前文本会作为 v{n} 保留在历史中，你可以随时切换回来。",
  "Nothing links here yet.": "尚无内容链接到这里。",
