  "Offline, retrying": "离线，正在重试",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "没有 <code>gemini mcp add</code> 的旧版 Gemini CLI：在 <code>~/.gemini/settings.json</code> 的 <code>mcpServers</code> 下添加服务器，使用 <code>httpUrl</code> 和相同的请求头。",
  "Older changes stay in History.": "较早的更改保留在历史中。",
  "Older messages were left out to fit the model's context.": "为适应模型上下文，已略去较早的消息。",
  "Older than 30 days": "超过 30 天",
  "Older than 7 days": "超过 7 天",
  "Older than 90 days": "超过 90 天",
  "Older versions of a note: read, compare, restore, and the trash.": "笔记的旧版本：读取、比较、恢复，以及回收站。",
  "Oldest entry": "最早记录",
  "On": "开",
  "On desktop, drag the edge of the chat list or the side panel to make it wider or narrower. Each keeps a minimum and remembers its width.": "在桌面端，拖动对话列表或侧边面板的边缘即可加宽或变窄。每个面板都有最小宽度，并会记住宽度。",
  "On its avatar, its sparks in the brain and every activity row.": "用于它的头像、大脑中的光点以及每条活动记录。",
  "On this page": "本页内容",
  "On: tap to switch off": "已开启：点击关闭",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "开启：{mnemo} 会记下对话中了解到的内容。关闭：只保留你在这里添加的。立即保存。",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "安装后，应用拥有独立图标，全屏打开，断网时仍可访问。",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "连接后，把这段粘贴到该应用的新对话中。它会让 AI 把所知道的存入 Memora。",
  "Once its app is set up, every call shows up here as it happens.": "设置好应用后，每次调用都会实时显示在这里。",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "{name} 连接后，它读取、写入和搜索的一切都会实时显示在这里。",
  "One address": "单个地址",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "每个应用或设备一个智能体：独立的密钥、在活动中独立的名称，可单独关闭。",
  "One click": "一键连接",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "一台设备或一个连接，例如 203.0.113.7。搜索“我的 IP 是什么”即可查看你的地址。",
  "One device or connection.": "一台设备或一个连接。",
  "One folder of notes that you and every connected AI share.": "一个由你和所有已连接 AI 共享的笔记文件夹。",
  "One is hidden by the folder rule.": "有一个被文件夹规则隐藏。",
  "One key per agent, its own permissions.": "每个智能体一个密钥，权限各自独立。",
  "One last step": "最后一步",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "一份所有智能体都能读写的记忆，而你可以查看、编辑和关联其中的一切。",
  "One memory for every AI": "一份记忆，服务所有 AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "有一条笔记显示此图片；删除后那里会显示为缺失。版本历史会保留它。",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "每行一条。它们会出现在新对话的建议中，标记为“你的”，并保留到你修改为止。",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "你和你的 AI 应用共享的一份私密记忆，任何事都不必解释两遍。",
  "One set of notes for every AI app": "一套笔记，供所有 AI 应用使用",
  "Online": "在线",
  "Only PNG, JPEG, WebP and GIF images can be added": "只能添加 PNG、JPEG、WebP 和 GIF 图片",
  "Only in the current version": "仅在当前版本中",
  "Only in version {n}": "仅在版本 {n} 中",
  "Only letters, digits and - _ / . can be used.": "只能使用字母、数字和 - _ / .",
  "Only looks at notes; changes nothing.": "只查看笔记，不做任何更改。",
  "Only looks things up and never writes. For agents with a read-only key.": "只查询，从不写入。适用于持有只读密钥的智能体。",
  "Only pictures in your newest message go to the image model, and you hear of it in a short toast.": "只有最新消息中的图片会交给图像模型，并通过简短提示告诉你。",
  "Only reads and answers; never changes notes": "只阅读和回答，从不修改笔记",
  "Only the agents you pick. New agents can’t see it.": "仅限你选择的智能体。新智能体无法看到。",
  "Only the first rule that fits a request counts.": "只有第一条匹配请求的规则生效。",
  "Only the latest questions go on the page at first; earlier ones come in as you scroll up or jump to them on the timeline.": "一开始只加载最新的问题；更早的内容在向上滚动或从时间线跳转时载入。",
