  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "粘贴到终端并按 <kbd>Enter</kbd>，然后在同一个终端中启动 Codex。",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "粘贴到终端并按 <kbd>Enter</kbd>。然后启动或重启 Claude Code：Memora 会自动加载。",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "粘贴到终端并按 <kbd>Enter</kbd>。然后启动或重启 Gemini CLI，输入 <code>/mcp</code> 查看 Memora。",
  "Paste it into the app where it asks for a key.": "粘贴到应用要求输入密钥的地方。",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "粘贴到文件中并保存，然后按 <b>Refresh</b>。Memora 会出现在列表中。",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "粘贴到文件中，保存并重启 Claude Desktop。此电脑需要安装 Node.js。",
