  "That address only opens on this computer or its network, which is fine when {app} runs here too.": "该地址只能在本机或其所在网络中打开，如果 {app} 也在这里运行就没问题。",
  "That address only opens on this computer or its network. {app} connects from the internet, so Memora needs an internet address with https. Ask whoever runs Memora to give it one.": "该地址只能在本机或其所在网络中打开。{app} 从互联网连接，因此 Memora 需要一个带 https 的互联网地址。请让 Memora 的管理员提供一个。",
