  "{mnemo} asks this model when you want a picture made.": "当你想生成图片时，{mnemo} 会请这个模型来做。",
  "{mnemo} button hidden. Bring it back from More, Show the {mnemo} button.": "{mnemo} 按钮已隐藏。可在“更多”中点“显示 {mnemo} 按钮”恢复。",
  "{mnemo} button hidden. Show it again here or from More.": "{mnemo} 按钮已隐藏。可在这里或“更多”中重新显示。",
  "{mnemo} could not write new ones just now. Check the model in Settings.": "{mnemo} 暂时写不出新的建议。请在设置中检查模型。",
  "{mnemo} hands pictures to this model when the chat model cannot see.": "当对话模型无法看图时，{mnemo} 会把图片交给这个模型。",
