  "{mnemo} looks after your notes": "{mnemo} 帮你打理笔记",
  "{mnemo} may learn about you": "{mnemo} 可以了解你",
  "{mnemo} only works in your notes. Each change shows in Activity and can be undone from History.": "{mnemo} 只在你的笔记中工作。每次修改都会显示在活动中，并可从历史中撤销。",
  "{mnemo} reads your vault in a new chat and keeps what it learns here.": "{mnemo} 会在新对话中阅读你的库，并把了解到的内容保存在这里。",
  "{mnemo} settings saved": "{mnemo} 设置已保存",
  "{mnemo} settings: models and keys": "{mnemo} 设置：模型和密钥",
  "{mnemo} starts sub-agents by itself when a task splits well; there is nothing to set up. They run on your default model, then the fallbacks, unless you name a model in the chat. Follow them, and switch their model, in Agents at the top right of the chat. They use tokens of their own, so in Ask first {mnemo} asks and says roughly how many; in Auto they just run. Saved at once.": "当任务适合拆分时，{mnemo} 会自行启动子智能体，无需任何设置。它们使用你的默认模型，然后是备用模型，除非你在对话中指定模型。在对话右上角的“智能体”中查看它们并切换模型。它们会消耗自己的 token，所以在“先询问”模式下 {mnemo} 会先问你并说明大约用量；在“自动”模式下直接运行。立即保存。",
  "{mnemo} stopped it": "{mnemo} 已停止它",
  "{mnemo} will keep that in mind": "{mnemo} 会记住的",
  "{mnemo} writes new suggestions from your recent notes (yours stay)": "{mnemo} 根据你最近的笔记写出新建议（你自己的保留）",
  "{mnemo}'s own ({n})": "{mnemo} 专属 ({n})",
  "{mnemo}'s own notes on how to talk to you, read in every chat. Click one to change it.": "{mnemo} 自己记下的与你交流的方式，每次对话都会读取。点击某条即可修改。",
  "{mnemo}, your notes agent": "{mnemo}，你的笔记智能体",
  "{mnemo}: {text}": "{mnemo}: {text}",
  "{model} cannot look at images; it got their names instead. Set a model that reads images in Settings to have them seen.": "{model} 无法查看图片，只收到了图片名称。请在设置中指定能读取图片的模型。",
  "{model} cannot look at images; the image model described them for it.": "{model} 无法查看图片；已由图片模型为其描述。",
  "{model} cannot read pictures, so it only gets their names. Set a model that reads images, or switch this chat's model.": "{model} 无法读取图片，只能收到图片名称。请设置能读取图片的模型，或更换此对话的模型。",
  "{model} cannot read pictures, so it only got their names. Set a model that reads images, or switch this chat's model.": "{model} 无法读取图片，只收到了图片名称。请设置能读取图片的模型，或更换此对话的模型。",
  "{model} cannot read pictures, so the image model looked at them for it.": "{model} 无法读取图片，因此由图片模型代为查看了。",
